#!/usr/bin/env python3
"""Validate and exclusively publish source-bound policy-evaluation evidence."""

from __future__ import annotations

import gzip
import hashlib
import sys
import json
import math
import os
import re
import shutil
from dataclasses import dataclass
from pathlib import Path
from typing import Any


SKILL_SCRIPTS = Path(__file__).resolve().parents[3] / ".agents/skills/monitor-tune-isaaclab-training/scripts"
sys.path.insert(0, str(SKILL_SCRIPTS))
from evidence_provenance import require_source_path, validate_provenance


SAFE_IDENTIFIER_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
SCENARIO_FIELDS = {
    "scenario_id",
    "scenario_overrides",
    "command_schedule",
    "duration_steps",
    "num_envs",
    "seed",
}
MOTION_GROUND_CONTACT_BODIES = (
    "right_thigh_link", "left_thigh_link", "right_shank_link", "left_shank_link",
)


class EvaluationEvidenceError(ValueError):
    """Raised when evaluation evidence is unsafe, conflicting, or incomplete."""


def validate_roa_velocity_mode(diagnostic: dict, config_ref: dict | None) -> bool:
    """Bind optional velocity signals to the hash-verified training configuration.

    Legacy evidence omitted the flag and always had an explicit velocity head.
    Disabled-mode evidence must supply the effective configuration, whose full
    provenance is validated by validate_evaluation_bundle before this check.
    """
    enabled = diagnostic.get("use_velocity_estimation", True)
    if type(enabled) is not bool:
        raise EvaluationEvidenceError("ROA velocity estimation flag must be boolean")
    if config_ref is None:
        if not enabled:
            raise EvaluationEvidenceError("disabled ROA velocity estimation requires effective-config evidence")
        return enabled
    from capture_effective_training_config import _parse_yaml, _optional_scalar
    try:
        reference = _validate_reference(config_ref, label="ROA effective config")
        config = _load_json_object(Path(reference["path"]), label="ROA effective config")
        root, _ = _parse_yaml(config["source_files"]["agent"]["content_utf8"], label="ROA agent config")
        configured = _optional_scalar(root, ("policy", "use_velocity_estimation"), label="ROA agent config")
        configured = True if configured is None else configured
        if type(configured) is not bool or configured != enabled:
            raise EvaluationEvidenceError("ROA velocity estimation mode differs from effective training config")
    except (KeyError, TypeError, ValueError) as exc:
        raise EvaluationEvidenceError(str(exc)) from exc
    return enabled


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _validate_identifier(name: str, value: Any) -> str:
    if not isinstance(value, str) or not SAFE_IDENTIFIER_RE.fullmatch(value):
        raise EvaluationEvidenceError(
            f"{name} must be a safe ASCII identifier (letters, digits, '.', '_', '-')"
        )
    return value


def _validate_sha256(name: str, value: Any) -> str:
    if not isinstance(value, str) or not SHA256_RE.fullmatch(value):
        raise EvaluationEvidenceError(f"{name} must be a lowercase SHA-256")
    return value


def _reject_unsafe_path(path: Path, *, label: str) -> None:
    if not path.is_absolute() or ".." in path.parts:
        raise EvaluationEvidenceError(
            f"{label} must be an absolute path without traversal"
        )
    current = Path(path.anchor)
    for component in path.parts[1:]:
        current /= component
        if current.is_symlink():
            raise EvaluationEvidenceError(
                f"{label} contains a symlinked path component: {current}"
            )


def _require_regular_file(
    path: Path,
    *,
    label: str,
    expected_sha256: str | None = None,
) -> dict[str, str]:
    _reject_unsafe_path(path, label=label)
    if not path.is_file():
        raise EvaluationEvidenceError(f"{label} is not an existing regular file")
    actual_sha256 = sha256_file(path)
    if expected_sha256 is not None:
        _validate_sha256(f"{label} SHA-256", expected_sha256)
        if actual_sha256 != expected_sha256:
            raise EvaluationEvidenceError(f"{label} SHA-256 mismatch")
    return {"path": str(path), "sha256": actual_sha256}


def _load_json_object(path: Path, *, label: str) -> dict[str, Any]:
    try:
        data = gzip.decompress(path.read_bytes()) if path.suffix == ".gz" else path.read_bytes()
        value = json.loads(data.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise EvaluationEvidenceError(f"cannot read {label}: {exc}") from exc
    if not isinstance(value, dict):
        raise EvaluationEvidenceError(f"{label} must be a JSON object")
    return value


def validate_roa_sensor_delay(telemetry: dict, delay_steps: int) -> None:
    """Recheck the recorded temporal contract from lossless frames, including resets."""
    from policy_evaluation_telemetry import ROA_SENSOR_COLUMNS, ROA_CURRENT_COLUMNS
    dt = telemetry.get("step_dt_seconds")
    if (type(delay_steps) is not int or delay_steps not in (0, 1)
            or isinstance(dt, bool) or not isinstance(dt, (int, float))
            or not math.isclose(dt, 0.02, rel_tol=0, abs_tol=1e-9)
            or telemetry.get("stride") != 1
            or telemetry.get("inputs", {}).get("resource_mode", {}).get("telemetry_stride") != 1):
        raise EvaluationEvidenceError("invalid ROA sensor delay period or telemetry stride")
    samples = telemetry.get("samples", [])
    if not samples:
        raise EvaluationEvidenceError("ROA sensor delay requires samples")
    reset_step = 0
    for step, sample in enumerate(samples):
        if sample.get("step") != step or type(sample.get("done")) is not bool:
            raise EvaluationEvidenceError("ROA sensor delay requires consecutive steps and reset flags")
        source = max(reset_step, step - delay_steps)
        source_values = sample.get("roa_sensor_source_step")
        ages = sample.get("roa_sensor_age_s")
        if (not isinstance(source_values, list) or len(source_values) != 1
                or isinstance(source_values[0], bool) or source_values[0] != source
                or not isinstance(ages, list) or len(ages) != 1
                or isinstance(ages[0], bool) or not isinstance(ages[0], (int, float))
                or not math.isclose(ages[0], (step - source) * dt, rel_tol=0, abs_tol=1e-9)):
            raise EvaluationEvidenceError("ROA sensor source step/age mismatch")
        for name in ("roa_fresh_policy_frame", "roa_delayed_policy_frame"):
            values = sample.get(name)
            if (not isinstance(values, list) or len(values) != 39
                    or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in values)):
                raise EvaluationEvidenceError("invalid ROA sensor frame")
        fresh = sample["roa_fresh_policy_frame"]
        delayed = sample["roa_delayed_policy_frame"]
        source_frame = samples[source]["roa_fresh_policy_frame"]
        if (any(delayed[i] != source_frame[i] for i in ROA_SENSOR_COLUMNS)
                or any(delayed[i] != fresh[i] for i in ROA_CURRENT_COLUMNS)):
            raise EvaluationEvidenceError("ROA sensor frame does not match source/current channels")
        if sample["done"]:
            reset_step = step + 1


def validate_scenario_contract(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != SCENARIO_FIELDS:
        raise EvaluationEvidenceError(
            "scenario contract must contain exactly scenario_id, scenario_overrides, "
            "command_schedule, duration_steps, num_envs, and seed"
        )
    _validate_identifier("scenario_id", value["scenario_id"])
    if not isinstance(value["scenario_overrides"], dict):
        raise EvaluationEvidenceError("scenario_overrides must be an object")
    for key, setting in value["scenario_overrides"].items():
        if key.startswith("evaluation."):
            from policy_evaluation_telemetry import (
                ROA_CONTROL_MODES, DWAQ_CONTROL_MODES, ROA_SENSOR_DELAY_OPTION, MOTION_MODES,
            )
            if key == ROA_SENSOR_DELAY_OPTION:
                if (type(setting) is not int or setting not in (0, 1)
                        or value["scenario_overrides"].get("evaluation.roa_mode") != "student"):
                    raise EvaluationEvidenceError("ROA sensor delay requires student control and zero or one step")
                continue
            if key == "evaluation.motion_sha256":
                if not isinstance(setting, str) or not re.fullmatch(r"[0-9a-f]{64}", setting):
                    raise EvaluationEvidenceError("invalid reference motion SHA-256")
                continue
            if key == "evaluation.motion_physics_window":
                if (not isinstance(setting, list) or len(setting) != 2
                        or any(type(v) is not int for v in setting) or not 0 <= setting[0] <= setting[1]):
                    raise EvaluationEvidenceError("invalid motion physics frame window")
                continue
            if key == "evaluation.motion_ground_contacts":
                if setting is not True:
                    raise EvaluationEvidenceError("motion ground contacts must be explicitly enabled")
                continue
            if key == "evaluation.landing_pull":
                validate_landing_pull_config(setting)
                continue
            modes = {"evaluation.roa_mode": ROA_CONTROL_MODES,
                     "evaluation.dwaq_mode": DWAQ_CONTROL_MODES,
                     "evaluation.motion_mode": MOTION_MODES,
                     "evaluation.motion_action_mode": ("mean", "sample")}
            if key not in modes or setting not in modes[key]:
                raise EvaluationEvidenceError("invalid evaluation controller or unknown evaluation option")
    overrides = value["scenario_overrides"]
    if "evaluation.motion_action_mode" in overrides and "evaluation.motion_mode" not in overrides:
        raise EvaluationEvidenceError("motion action sampling requires motion diagnostics")
    if "evaluation.motion_ground_contacts" in overrides and "evaluation.motion_physics_window" not in overrides:
        raise EvaluationEvidenceError("motion ground contacts require physics capture")
    if "evaluation.landing_pull" in overrides and (
            overrides.get("evaluation.motion_mode") != "nominal_start"
            or "evaluation.motion_physics_window" not in overrides):
        raise EvaluationEvidenceError("landing pull requires nominal motion and full physics capture")
    if "evaluation.motion_physics_window" in overrides and "evaluation.motion_mode" not in overrides:
        raise EvaluationEvidenceError("physics window requires motion diagnostics")
    if ("evaluation.motion_mode" in overrides) != ("evaluation.motion_sha256" in overrides):
        raise EvaluationEvidenceError("motion mode and reference SHA-256 must be supplied together")
    if "evaluation.motion_mode" in overrides and any(
        key in overrides for key in ("evaluation.roa_mode", "evaluation.dwaq_mode")
    ):
        raise EvaluationEvidenceError("motion and velocity diagnostic modes are mutually exclusive")
    if all(key in value["scenario_overrides"] for key in ("evaluation.roa_mode", "evaluation.dwaq_mode")):
        raise EvaluationEvidenceError("ROA and DWAQ diagnostic modes are mutually exclusive")
    if not isinstance(value["command_schedule"], list):
        raise EvaluationEvidenceError("command_schedule must be an array")
    for field in ("duration_steps", "num_envs"):
        field_value = value[field]
        if (
            isinstance(field_value, bool)
            or not isinstance(field_value, int)
            or field_value <= 0
        ):
            raise EvaluationEvidenceError(f"{field} must be a positive integer")
    if isinstance(value["seed"], bool) or not isinstance(value["seed"], int):
        raise EvaluationEvidenceError("seed must be an integer")

    previous_end = -1
    for index, segment in enumerate(value["command_schedule"]):
        if not isinstance(segment, dict) or set(segment) != {
            "start_step",
            "end_step",
            "command",
        }:
            raise EvaluationEvidenceError(
                f"command schedule segment {index} is invalid"
            )
        start = segment["start_step"]
        end = segment["end_step"]
        command = segment["command"]
        if (
            isinstance(start, bool)
            or not isinstance(start, int)
            or isinstance(end, bool)
            or not isinstance(end, int)
            or start != previous_end + 1
            or end < start
            or end >= value["duration_steps"]
        ):
            raise EvaluationEvidenceError(
                "command schedule must be ordered, contiguous, and within duration"
            )
        if (
            not isinstance(command, list)
            or len(command) != 3
            or any(
                isinstance(item, bool)
                or not isinstance(item, (int, float))
                or not math.isfinite(float(item))
                for item in command
            )
        ):
            raise EvaluationEvidenceError(
                "command schedule values must be finite [vx, vy, yaw_rate]"
            )
        previous_end = end
    if value["command_schedule"] and previous_end != value["duration_steps"] - 1:
        raise EvaluationEvidenceError(
            "command schedule must cover every evaluation step"
        )
    try:
        canonical_json(value)
    except (TypeError, ValueError) as exc:
        raise EvaluationEvidenceError(f"scenario contract is not finite JSON: {exc}") from exc
    return value


def build_scenario_contract(
    *,
    scenario_id: str,
    scenario_overrides_json: str,
    command_schedule_json: str,
    duration_steps: int,
    num_envs: int,
    seed: int,
) -> dict[str, Any]:
    try:
        scenario_overrides = json.loads(scenario_overrides_json)
    except json.JSONDecodeError as exc:
        raise EvaluationEvidenceError(
            f"invalid scenario_overrides_json at column {exc.colno}: {exc.msg}"
        ) from exc
    try:
        command_schedule = json.loads(command_schedule_json)
    except json.JSONDecodeError as exc:
        raise EvaluationEvidenceError(
            f"invalid command_schedule_json at column {exc.colno}: {exc.msg}"
        ) from exc
    return validate_scenario_contract(
        {
            "scenario_id": scenario_id,
            "scenario_overrides": scenario_overrides,
            "command_schedule": command_schedule,
            "duration_steps": duration_steps,
            "num_envs": num_envs,
            "seed": seed,
        }
    )


def scenario_sha256(contract: dict[str, Any]) -> str:
    validate_scenario_contract(contract)
    return sha256_bytes(canonical_json(contract).encode("utf-8"))


def expected_evaluation_paths(
    repo_root: Path,
    *,
    task: str,
    run_id: str,
    evaluation_id: str,
    batch_id: str | None = None,
) -> dict[str, Path]:
    _reject_unsafe_path(repo_root, label="repository root")
    _validate_identifier("task", task)
    _validate_identifier("run_id", run_id)
    _validate_identifier("evaluation_id", evaluation_id)
    evaluation_dir = (
        repo_root
        / "learnings"
        / "policy_tuning"
        / task
        / run_id
        / "evidence"
        / "play"
        / evaluation_id
    )
    if batch_id is not None:
        _validate_identifier("batch_id", batch_id)
        evaluation_dir = repo_root / "learnings" / "policy_tuning" / task / run_id / "evaluations" / batch_id / "raw" / evaluation_id
    return {
        "evaluation_dir": evaluation_dir,
        "result": evaluation_dir / "result.json",
        "telemetry": evaluation_dir / ("telemetry.json.gz" if batch_id else "telemetry.json"),
        "video": evaluation_dir / "video.mp4",
    }


def _require_exact_path(actual: Path, expected: Path, *, label: str) -> None:
    _reject_unsafe_path(actual, label=label)
    if actual != expected:
        raise EvaluationEvidenceError(
            f"{label} is outside the current run/evaluation evidence layout"
        )


def _require_new_targets(paths: dict[str, Path]) -> None:
    for label in ("result", "telemetry", "video"):
        path = paths[label]
        _reject_unsafe_path(path, label=f"{label} target")
        if path.exists() or path.is_symlink():
            raise EvaluationEvidenceError(f"{label} target already exists: {path}")


def _load_bound_run_identity(
    path: Path,
    *,
    expected_file_sha256: str,
    repo_root: Path,
    task: str,
    run_id: str,
    seed: int,
    scenario_contract: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, str]]:
    reference = _require_regular_file(
        path,
        label="run identity",
        expected_sha256=expected_file_sha256,
    )
    identity = _load_json_object(path, label="run identity")
    try:
        require_source_path(path, repo_root / "learnings" / "policy_tuning" / task / run_id, "context")
        if identity.get("version") == 2:
            from capture_run_identity import validate_run_identity
            validate_run_identity(identity)
    except ValueError as exc:
        raise EvaluationEvidenceError(str(exc)) from exc
    payload = {key: value for key, value in identity.items() if key != "identity_sha256"}
    internal_sha256 = sha256_bytes(canonical_json(payload).encode("utf-8"))
    if identity.get("identity_sha256") != internal_sha256:
        raise EvaluationEvidenceError("run identity internal SHA-256 mismatch")
    for field, expected in (("task", task), ("run_id", run_id), ("seed", seed)):
        if identity.get(field) != expected:
            raise EvaluationEvidenceError(f"run identity {field} mismatch")
    source = identity.get("source")
    if not isinstance(source, dict) or source.get("repository_root") != str(repo_root):
        raise EvaluationEvidenceError("run identity repository root mismatch")
    if identity["version"] == 1:
        evaluation = identity.get("evaluation_scenario")
        if not isinstance(evaluation, dict):
            raise EvaluationEvidenceError("run identity evaluation_scenario is missing")
        identity_contract = validate_scenario_contract(evaluation.get("contract"))
        expected_scenario_sha256 = scenario_sha256(identity_contract)
        if evaluation.get("sha256") != expected_scenario_sha256:
            raise EvaluationEvidenceError("run identity scenario SHA-256 mismatch")
        if identity_contract != scenario_contract:
            raise EvaluationEvidenceError("run identity scenario contract mismatch")
    return identity, {
        "path": reference["path"],
        "file_sha256": reference["sha256"],
        "identity_sha256": internal_sha256,
    }


@dataclass(frozen=True)
class EvaluationPlan:
    repo_root: Path
    task: str
    run_id: str
    evaluation_id: str
    result_path: Path
    telemetry_path: Path | None
    video_path: Path | None
    canonical_paths: dict[str, Path]
    checkpoint: dict[str, str]
    artifact: dict[str, str]
    artifact_kind: str
    run_identity: dict[str, str]
    scenario_contract: dict[str, Any]
    scenario_sha256: str
    batch_id: str | None = None
    effective_config: dict | None = None
    scenario_evidence: dict | None = None


def preflight_evaluation(
    *,
    repo_root: Path,
    task: str,
    run_id: str,
    evaluation_id: str,
    result_path: Path,
    telemetry_path: Path | None,
    video_path: Path | None,
    checkpoint_path: Path,
    checkpoint_sha256: str,
    artifact_kind: str,
    artifact_path: Path,
    artifact_sha256: str,
    run_identity_path: Path,
    run_identity_file_sha256: str,
    scenario_contract: dict[str, Any],
    batch_id: str | None = None,
    effective_config: dict | None = None,
    scenario_evidence: dict | None = None,
) -> EvaluationPlan:
    if artifact_kind not in {"native", "jit", "onnx"}:
        raise EvaluationEvidenceError("artifact_kind must be native, jit, or onnx")
    repo_root = repo_root.absolute()
    canonical_paths = expected_evaluation_paths(
        repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        batch_id=batch_id,
    )
    evaluation_dir = canonical_paths["evaluation_dir"]
    _reject_unsafe_path(evaluation_dir, label="evaluation directory")
    if not evaluation_dir.is_dir():
        raise EvaluationEvidenceError(
            "evaluation directory must be prepared by prepare_evidence_layout.py"
        )
    _require_exact_path(result_path, canonical_paths["result"], label="result_path")
    if telemetry_path is not None:
        _require_exact_path(
            telemetry_path,
            canonical_paths["telemetry"],
            label="telemetry_path",
        )
    if video_path is not None:
        _require_exact_path(video_path, canonical_paths["video"], label="video_path")
    _require_new_targets(canonical_paths)
    if batch_id is not None and (evaluation_dir / ".attempt-used").exists():
        raise EvaluationEvidenceError("attempt ID already used")

    checkpoint = _require_regular_file(
        checkpoint_path,
        label="checkpoint",
        expected_sha256=checkpoint_sha256,
    )
    artifact = _require_regular_file(
        artifact_path,
        label="artifact",
        expected_sha256=artifact_sha256,
    )
    scenario_contract = validate_scenario_contract(scenario_contract)
    identity, run_identity = _load_bound_run_identity(
        run_identity_path,
        expected_file_sha256=run_identity_file_sha256,
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        seed=scenario_contract["seed"],
        scenario_contract=scenario_contract,
    )
    if batch_id is not None:
        try:
            validate_provenance(identity, effective_config, scenario_evidence, scenario_contract, live=True)
        except (ValueError, OSError, KeyError, TypeError) as exc:
            raise EvaluationEvidenceError(str(exc)) from exc
    elif identity["version"] != 1 or effective_config is not None or scenario_evidence is not None:
        raise EvaluationEvidenceError("new provenance requires a batch_id")
    return EvaluationPlan(
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        result_path=result_path,
        telemetry_path=telemetry_path,
        video_path=video_path,
        canonical_paths=canonical_paths,
        checkpoint=checkpoint,
        artifact=artifact,
        artifact_kind=artifact_kind,
        run_identity=run_identity,
        scenario_contract=scenario_contract,
        scenario_sha256=scenario_sha256(scenario_contract),
        batch_id=batch_id,
        effective_config=effective_config,
        scenario_evidence=scenario_evidence,
    )


def _write_new_json(path: Path, value: dict[str, Any]) -> None:
    encoded = json.dumps(
        value,
        indent=2,
        sort_keys=True,
        ensure_ascii=False,
        allow_nan=False,
    ) + "\n"
    with path.open("x", encoding="utf-8") as stream:
        stream.write(encoded)


class EvaluationPublisher:
    """Claim one evaluation directory and publish result last without overwrite."""

    def __init__(self, plan: EvaluationPlan) -> None:
        self.plan = plan
        self.evaluation_dir = plan.canonical_paths["evaluation_dir"]
        self.claim_path = self.evaluation_dir / ".publish-claim"
        self.attempt_dir = self.evaluation_dir / ".attempt"
        self.video_work_path = self.attempt_dir / "video.mp4"
        self._entered = False
        self._published = False
        self._claim_identity: tuple[int, int] | None = None
        self._attempt_identity: tuple[int, int] | None = None

    def __enter__(self) -> "EvaluationPublisher":
        _require_new_targets(self.plan.canonical_paths)
        try:
            with self.claim_path.open("x", encoding="utf-8") as stream:
                stream.write(self.plan.evaluation_id + "\n")
        except FileExistsError as exc:
            raise EvaluationEvidenceError(
                f"evaluation publication is already claimed: {self.claim_path}"
            ) from exc
        claim_stat = self.claim_path.stat(follow_symlinks=False)
        self._claim_identity = (claim_stat.st_dev, claim_stat.st_ino)
        try:
            if self.plan.batch_id is not None:
                with (self.evaluation_dir / ".attempt-used").open("x") as stream:
                    stream.write(self.plan.evaluation_id + "\n")
            self.attempt_dir.mkdir()
        except OSError as exc:
            if self._still_owned(self.claim_path, self._claim_identity):
                self.claim_path.unlink()
            self._claim_identity = None
            raise EvaluationEvidenceError(
                f"cannot create exclusive evaluation attempt: {exc}"
            ) from exc
        attempt_stat = self.attempt_dir.stat(follow_symlinks=False)
        self._attempt_identity = (attempt_stat.st_dev, attempt_stat.st_ino)
        self._entered = True
        return self

    @staticmethod
    def _still_owned(path: Path, identity: tuple[int, int] | None) -> bool:
        if identity is None:
            return False
        try:
            stat_result = path.stat(follow_symlinks=False)
        except FileNotFoundError:
            return False
        return (stat_result.st_dev, stat_result.st_ino) == identity

    def _cleanup_owned(self) -> None:
        if self._still_owned(self.attempt_dir, self._attempt_identity):
            shutil.rmtree(self.attempt_dir)
        if self._still_owned(self.claim_path, self._claim_identity):
            self.claim_path.unlink()
        self._attempt_identity = None
        self._claim_identity = None

    def close(self) -> None:
        """Release only this publisher's temporary claim and attempt data."""
        if self._entered:
            self._cleanup_owned()
            self._entered = False

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        self.close()

    def publish(
        self,
        result: dict[str, Any],
        *,
        telemetry: dict[str, Any] | None,
        video_source: Path | None,
    ) -> dict[str, Any]:
        if not self._entered or self._published:
            raise EvaluationEvidenceError("evaluation publisher is not active")
        if (telemetry is None) != (self.plan.telemetry_path is None):
            raise EvaluationEvidenceError("telemetry payload does not match telemetry_path")
        if (video_source is None) != (self.plan.video_path is None):
            raise EvaluationEvidenceError("video payload does not match video_path")
        _require_new_targets(self.plan.canonical_paths)

        telemetry_work = self.attempt_dir / "telemetry.json"
        result_work = self.attempt_dir / "result.json"
        telemetry_reference = None
        if telemetry is not None:
            if self.plan.batch_id is not None:
                encoded = (json.dumps(telemetry, sort_keys=True, ensure_ascii=False, allow_nan=False) + "\n").encode("utf-8")
                with telemetry_work.open("xb") as stream:
                    stream.write(gzip.compress(encoded, mtime=0))
            else:
                _write_new_json(telemetry_work, telemetry)
            telemetry_reference = {
                "path": str(self.plan.telemetry_path),
                "sha256": sha256_file(telemetry_work),
            }
        video_reference = None
        if video_source is not None:
            if video_source != self.video_work_path:
                raise EvaluationEvidenceError("video source is outside the evaluation attempt")
            video_work = _require_regular_file(video_source, label="attempt video")
            video_reference = {
                "path": str(self.plan.video_path),
                "sha256": video_work["sha256"],
            }

        published_result = dict(result)
        published_result["result_path"] = str(self.plan.result_path)
        published_result["outputs"] = {
            "telemetry": telemetry_reference,
            "video": video_reference,
        }
        _write_new_json(result_work, published_result)

        sources_and_targets: list[tuple[Path, Path]] = []
        if video_source is not None:
            assert self.plan.video_path is not None
            sources_and_targets.append((video_source, self.plan.video_path))
        if telemetry is not None:
            assert self.plan.telemetry_path is not None
            sources_and_targets.append((telemetry_work, self.plan.telemetry_path))
        created_targets: list[Path] = []
        try:
            for source, target in sources_and_targets:
                os.link(source, target, follow_symlinks=False)
                created_targets.append(target)
            validate_evaluation_bundle(
                result_work,
                canonical_result_path=self.plan.result_path,
            )
            os.link(result_work, self.plan.result_path, follow_symlinks=False)
            created_targets.append(self.plan.result_path)
            validate_evaluation_bundle(self.plan.result_path)
        except (OSError, EvaluationEvidenceError) as exc:
            for target in reversed(created_targets):
                target.unlink(missing_ok=True)
            raise EvaluationEvidenceError(
                f"exclusive evaluation publication failed: {exc}"
            ) from exc
        self._published = True
        return published_result


def close_evaluation_resources(
    publisher: EvaluationPublisher,
    simulation_app: Any,
) -> None:
    """Release publication state before shutting down Isaac Sim."""
    try:
        publisher.close()
    finally:
        simulation_app.close()


def _validate_reference(value: Any, *, label: str) -> dict[str, str]:
    if not isinstance(value, dict) or set(value) != {"path", "sha256"}:
        raise EvaluationEvidenceError(f"{label} reference is invalid")
    path_value = value.get("path")
    if not isinstance(path_value, str):
        raise EvaluationEvidenceError(f"{label} path is invalid")
    reference = _require_regular_file(
        Path(path_value),
        label=label,
        expected_sha256=value.get("sha256"),
    )
    return reference


def validate_evaluation_bundle(
    result_path: Path,
    *,
    canonical_result_path: Path | None = None,
) -> dict[str, Any]:
    """Revalidate a final bundle or a private result before final publication."""
    result_reference = _require_regular_file(result_path, label="evaluation result")
    result = _load_json_object(result_path, label="evaluation result")
    if result.get("version") not in {2, 3} or result.get("status") != "completed":
        raise EvaluationEvidenceError("evaluation result must be completed version 2 or 3")
    if result["version"] == 3 and result.get("layout_version") != 2:
        raise EvaluationEvidenceError("new result requires layout_version 2")
    evaluation = result.get("evaluation")
    inputs = result.get("inputs")
    outputs = result.get("outputs")
    if not isinstance(evaluation, dict) or not isinstance(inputs, dict):
        raise EvaluationEvidenceError("evaluation result binding is incomplete")
    if not isinstance(outputs, dict) or set(outputs) != {"telemetry", "video"}:
        raise EvaluationEvidenceError("evaluation result outputs are incomplete")
    task = _validate_identifier("result task", evaluation.get("task"))
    run_id = _validate_identifier("result run_id", evaluation.get("run_id"))
    evaluation_id = _validate_identifier(
        "result evaluation_id", evaluation.get("evaluation_id")
    )
    _validate_identifier("result candidate_id", evaluation.get("candidate_id"))
    _validate_identifier("result runner", evaluation.get("runner"))
    resource_mode = inputs.get("resource_mode")
    if not isinstance(resource_mode, dict):
        raise EvaluationEvidenceError("result resource mode is missing")
    for field in (
        "training_overlap",
        "idle_gpu_required",
        "video_requested",
        "telemetry_requested",
    ):
        if not isinstance(resource_mode.get(field), bool):
            raise EvaluationEvidenceError(f"result resource mode {field} is invalid")
    run_identity = inputs.get("run_identity")
    if not isinstance(run_identity, dict):
        raise EvaluationEvidenceError("result run identity reference is missing")
    run_identity_path = run_identity.get("path")
    if not isinstance(run_identity_path, str):
        raise EvaluationEvidenceError("result run identity path is invalid")
    identity_document = _load_json_object(
        Path(run_identity_path), label="result run identity"
    )
    source = identity_document.get("source")
    if not isinstance(source, dict) or not isinstance(source.get("repository_root"), str):
        raise EvaluationEvidenceError("result run identity repository root is missing")
    repo_root = Path(source["repository_root"])
    expected_paths = expected_evaluation_paths(
        repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        batch_id=evaluation.get("batch_id") if result["version"] == 3 else None,
    )
    declared_result_path = canonical_result_path or result_path
    _require_exact_path(
        declared_result_path,
        expected_paths["result"],
        label="result_path",
    )
    if result.get("result_path") != str(declared_result_path):
        raise EvaluationEvidenceError("embedded result_path mismatch")

    scenario = inputs.get("scenario")
    if not isinstance(scenario, dict) or set(scenario) != {"contract", "sha256"}:
        raise EvaluationEvidenceError("result scenario binding is invalid")
    scenario_contract = validate_scenario_contract(scenario["contract"])
    if scenario["sha256"] != scenario_sha256(scenario_contract):
        raise EvaluationEvidenceError("result scenario SHA-256 mismatch")
    loaded_identity, bound_identity = _load_bound_run_identity(
        Path(run_identity_path),
        expected_file_sha256=run_identity.get("file_sha256"),
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        seed=scenario_contract["seed"],
        scenario_contract=scenario_contract,
    )
    if run_identity.get("identity_sha256") != bound_identity["identity_sha256"]:
        raise EvaluationEvidenceError("result run identity SHA-256 mismatch")
    if result["version"] == 3:
        _validate_identifier("batch_id", evaluation.get("batch_id"))
        if loaded_identity["runner"] != evaluation["runner"]:
            raise EvaluationEvidenceError("result runner mismatch")
        try:
            validate_provenance(loaded_identity, inputs.get("effective_config"), inputs.get("scenario_evidence"), scenario_contract)
        except (ValueError, OSError, KeyError, TypeError) as exc:
            raise EvaluationEvidenceError(str(exc)) from exc
    elif loaded_identity["version"] != 1:
        raise EvaluationEvidenceError("legacy result requires legacy identity")

    checkpoint = _validate_reference(inputs.get("checkpoint"), label="result checkpoint")
    artifact = inputs.get("artifact")
    if not isinstance(artifact, dict) or set(artifact) != {"kind", "path", "sha256"}:
        raise EvaluationEvidenceError("result artifact reference is invalid")
    artifact_reference = _validate_reference(
        {"path": artifact["path"], "sha256": artifact["sha256"]},
        label="result artifact",
    )

    output_references: dict[str, dict[str, str] | None] = {}
    for label in ("telemetry", "video"):
        value = outputs[label]
        if value is None:
            output_references[label] = None
            continue
        reference = _validate_reference(value, label=f"result {label}")
        _require_exact_path(
            Path(reference["path"]),
            expected_paths[label],
            label=f"result {label}",
        )
        output_references[label] = reference
    if resource_mode["telemetry_requested"] != (
        output_references["telemetry"] is not None
    ):
        raise EvaluationEvidenceError("telemetry resource mode/output mismatch")
    if resource_mode["video_requested"] != (
        output_references["video"] is not None
    ):
        raise EvaluationEvidenceError("video resource mode/output mismatch")
    telemetry_reference = output_references["telemetry"]
    if telemetry_reference is not None:
        telemetry = _load_json_object(
            Path(telemetry_reference["path"]), label="evaluation telemetry"
        )
        if result["version"] == 3 and telemetry.get("version") != 4:
            raise EvaluationEvidenceError("new result requires telemetry version 4")
        if telemetry.get("evaluation") != evaluation:
            raise EvaluationEvidenceError("telemetry evaluation binding mismatch")
        if telemetry.get("inputs") != inputs:
            raise EvaluationEvidenceError("telemetry input binding mismatch")

    roa_mode = scenario_contract["scenario_overrides"].get("evaluation.roa_mode")
    if roa_mode is not None:
        from policy_evaluation_telemetry import roa_diagnostic_signals
        if evaluation["runner"] != "OnPolicyRunnerROA" or artifact["kind"] != "native":
            raise EvaluationEvidenceError("ROA diagnostics require native OnPolicyRunnerROA")
        if telemetry_reference is None:
            raise EvaluationEvidenceError("ROA diagnostics require telemetry")
        diagnostic = result.get("roa_diagnostics", {})
        if (diagnostic.get("controller") != roa_mode
                or diagnostic.get("sampling_phase") != "pre_action"
                or diagnostic.get("velocity_units") != "m/s"
                or telemetry.get("roa_diagnostics") != diagnostic):
            raise EvaluationEvidenceError("ROA diagnostic mode/units/timing binding mismatch")
        scales = diagnostic.get("velocity_observation_scale")
        if (not isinstance(scales, list) or len(scales) not in (1, 3)
                or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or x <= 0 for x in scales)):
            raise EvaluationEvidenceError("invalid ROA velocity observation scale")
        velocity_enabled = validate_roa_velocity_mode(diagnostic, inputs.get("effective_config"))
        try:
            required = set(roa_diagnostic_signals(roa_mode, velocity_enabled))
            from policy_evaluation_telemetry import ROA_SENSOR_DELAY_OPTION, ROA_SENSOR_DELAY_SIGNALS
            if ROA_SENSOR_DELAY_OPTION in scenario_contract["scenario_overrides"]:
                required.update(ROA_SENSOR_DELAY_SIGNALS)
        except ValueError as exc:
            raise EvaluationEvidenceError(str(exc)) from exc
        if not required.issubset(telemetry.get("required_signals", [])):
            raise EvaluationEvidenceError("ROA diagnostic signals must be required")
        for sample in telemetry.get("samples", []):
            for name in required:
                values = sample.get(name)
                if not isinstance(values, list) or not values or any(not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(x) for x in values):
                    raise EvaluationEvidenceError(f"invalid or missing ROA signal {name}")
            if sample["action"] != sample[f"roa_{roa_mode}_action"]:
                raise EvaluationEvidenceError("executed action differs from selected ROA branch")
        expected = len(range(0, scenario_contract["duration_steps"], resource_mode["telemetry_stride"]))
        if len(telemetry.get("samples", [])) != expected:
            raise EvaluationEvidenceError("ROA diagnostic sample count mismatch")
        if any(not telemetry.get("signal_status", {}).get(name, {}).get("complete") for name in required):
            raise EvaluationEvidenceError("incomplete ROA diagnostic signals")
        if ROA_SENSOR_DELAY_OPTION in scenario_contract["scenario_overrides"]:
            validate_roa_sensor_delay(telemetry, scenario_contract["scenario_overrides"][ROA_SENSOR_DELAY_OPTION])

    dwaq_mode = scenario_contract["scenario_overrides"].get("evaluation.dwaq_mode")
    if dwaq_mode is not None:
        from policy_evaluation_telemetry import DWAQ_DIAGNOSTIC_SIGNALS
        if evaluation["runner"] != "OnPolicyRunnerDwaq" or artifact["kind"] != "native":
            raise EvaluationEvidenceError("DWAQ diagnostics require native OnPolicyRunnerDwaq")
        if telemetry_reference is None:
            raise EvaluationEvidenceError("DWAQ diagnostics require telemetry")
        diagnostic = result.get("dwaq_diagnostics", {})
        if (diagnostic.get("controller") != dwaq_mode
                or diagnostic.get("sampling_phase") != "pre_action"
                or diagnostic.get("velocity_units") != "m/s"
                or telemetry.get("dwaq_diagnostics") != diagnostic):
            raise EvaluationEvidenceError("DWAQ diagnostic mode/units/timing binding mismatch")
        scales = diagnostic.get("velocity_observation_scale")
        if (not isinstance(scales, list) or len(scales) not in (1, 3)
                or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or x <= 0 for x in scales)):
            raise EvaluationEvidenceError("invalid DWAQ velocity observation scale")
        required = set(DWAQ_DIAGNOSTIC_SIGNALS)
        if not required.issubset(telemetry.get("required_signals", [])):
            raise EvaluationEvidenceError("DWAQ diagnostic signals must be required")
        for sample in telemetry.get("samples", []):
            for name in required:
                values = sample.get(name)
                if not isinstance(values, list) or not values or any(not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(x) for x in values):
                    raise EvaluationEvidenceError(f"invalid or missing DWAQ signal {name}")
            if sample["action"] != sample[f"dwaq_{dwaq_mode}_action"]:
                raise EvaluationEvidenceError("executed action differs from selected DWAQ branch")
        expected = len(range(0, scenario_contract["duration_steps"], resource_mode["telemetry_stride"]))
        if len(telemetry.get("samples", [])) != expected:
            raise EvaluationEvidenceError("DWAQ diagnostic sample count mismatch")
        if any(not telemetry.get("signal_status", {}).get(name, {}).get("complete") for name in required):
            raise EvaluationEvidenceError("incomplete DWAQ diagnostic signals")

    if "evaluation.motion_mode" in scenario_contract["scenario_overrides"]:
        if telemetry_reference is None:
            raise EvaluationEvidenceError("motion diagnostics require telemetry")
        validate_motion_telemetry(result, telemetry, scenario_contract)

    return {
        "status": "valid",
        "result": result_reference,
        "checkpoint": checkpoint,
        "artifact": artifact_reference,
        "run_identity": bound_identity,
        "scenario_sha256": scenario["sha256"],
        "outputs": output_references,
    }


def validate_landing_pull_config(config):
    fields = {"delta_v_m_s", "angle_deg", "duration_s", "body_name", "point_b_m",
              "contact_threshold_n", "airborne_time_s", "geometry"}
    if not isinstance(config, dict) or set(config) != fields:
        raise EvaluationEvidenceError("invalid landing pull fields")
    for key in ("delta_v_m_s", "angle_deg", "duration_s", "contact_threshold_n", "airborne_time_s"):
        if type(config[key]) not in (int, float) or not math.isfinite(config[key]):
            raise EvaluationEvidenceError("nonfinite landing pull parameter")
    if (not 0 <= config["delta_v_m_s"] <= 2 or not 0 <= config["angle_deg"] <= 90
            or not 0 < config["duration_s"] <= .2 or config["contact_threshold_n"] <= 0
            or config["airborne_time_s"] < .005 or config["body_name"] != "base_link"):
        raise EvaluationEvidenceError("landing pull parameter out of bounded range")
    point = config["point_b_m"]
    if (not isinstance(point, list) or len(point) != 3
            or any(type(v) not in (int, float) or not math.isfinite(v) for v in point)):
        raise EvaluationEvidenceError("invalid landing pull attachment point")
    _validate_reference(config["geometry"], label="pull attachment geometry")


def validate_motion_telemetry(result, telemetry, scenario):
    """Recompute motion metrics and verify timing/completeness beyond output hashes."""
    from policy_evaluation_telemetry import (
        MOTION_REQUIRED_SIGNALS, MOTION_VECTOR_WIDTHS, MOTION_JOINT_SIGNALS,
        MOTION_BODY_SIGNALS, summarize_motion_samples,
    )
    diagnostic = result.get("motion_diagnostics", {})
    resource = result["inputs"]["resource_mode"]
    modes = (resource.get("idle_gpu_required"), resource.get("training_overlap"))
    if (result.get("artifact") != "native" or result.get("runner") != "OnPolicyRunner"
            or scenario["num_envs"] != 1 or scenario["command_schedule"]
            or resource.get("telemetry_stride") != 1 or resource.get("video_requested")
            or any(type(value) is not bool for value in modes)
            or modes not in ((True, False), (False, True))
            or (resource.get("training_overlap") and scenario["duration_steps"] > 2000)):
        raise EvaluationEvidenceError("invalid motion evaluation resource contract")
    if (diagnostic != telemetry.get("motion_diagnostics")
            or diagnostic.get("mode") != scenario["scenario_overrides"]["evaluation.motion_mode"]
            or diagnostic.get("sampling_phase") != "post_physics_pre_reset"):
        raise EvaluationEvidenceError("motion diagnostic binding/timing mismatch")
    motion = _validate_reference(diagnostic.get("motion_file"), label="reference motion")
    if motion["sha256"] != scenario["scenario_overrides"]["evaluation.motion_sha256"]:
        raise EvaluationEvidenceError("motion data SHA-256 differs from scenario")
    count = diagnostic.get("frame_count")
    if type(count) is not int or count < 2:
        raise EvaluationEvidenceError("invalid motion frame count")
    import numpy as np
    with np.load(motion["path"], allow_pickle=False) as reference:
        if count != len(reference["joint_pos"]) or diagnostic.get("fps") != float(reference["fps"].item()):
            raise EvaluationEvidenceError("motion frame count/fps differs from bound data")
    dt = telemetry.get("step_dt_seconds")
    if type(dt) not in (int, float) or not math.isclose(dt * diagnostic["fps"], 1.0, abs_tol=1e-6):
        raise EvaluationEvidenceError("motion fps/control timestep mismatch")
    samples = telemetry.get("samples", [])
    if len(samples) != scenario["duration_steps"]:
        raise EvaluationEvidenceError("motion sample count mismatch")
    requested_action_mode = scenario["scenario_overrides"].get("evaluation.motion_action_mode", "mean")
    action_sampling = diagnostic.get("action_sampling")
    legacy_mean = action_sampling is None and "evaluation.motion_action_mode" not in scenario["scenario_overrides"]
    if not legacy_mean:
        if not isinstance(action_sampling, dict) or action_sampling.get("mode") != requested_action_mode:
            raise EvaluationEvidenceError("motion action sampling mode differs from scenario")
        if requested_action_mode == "mean":
            if action_sampling != {"mode": "mean"}:
                raise EvaluationEvidenceError("mean motion actions must not claim sampled noise")
        else:
            std = action_sampling.get("action_std")
            checkpoint = result.get("inputs", {}).get("checkpoint", {})
            if (set(action_sampling) != {"mode", "distribution", "std_source", "checkpoint_sha256",
                                        "noise_std_type", "action_std"}
                    or action_sampling.get("distribution") != "Normal"
                    or action_sampling.get("std_source") != "checkpoint"
                    or action_sampling.get("noise_std_type") not in ("scalar", "log")
                    or not re.fullmatch(r"[0-9a-f]{64}", str(action_sampling.get("checkpoint_sha256", "")))
                    or action_sampling.get("checkpoint_sha256") != checkpoint.get("sha256")
                    or not isinstance(std, list) or not std
                    or not samples or len(std) != len(samples[0].get("action", []))
                    or any(type(v) not in (int, float) or not math.isfinite(v) or v <= 0 for v in std)):
                raise EvaluationEvidenceError("invalid checkpoint-bound motion action standard deviations")
            bound_checkpoint = _validate_reference(checkpoint, label="motion action checkpoint")
            try:
                import torch
                state = torch.load(bound_checkpoint["path"], map_location="cpu", weights_only=True)["model_state_dict"]
                saved_std = state["std" if action_sampling["noise_std_type"] == "scalar" else "log_std"]
                if not isinstance(saved_std, torch.Tensor) or saved_std.ndim != 1:
                    raise ValueError("checkpoint action std must be a vector")
                if action_sampling["noise_std_type"] == "log":
                    saved_std = saved_std.exp()
                recorded_std = torch.tensor(std, dtype=torch.float64)
                if (saved_std.shape != recorded_std.shape
                        or not torch.allclose(saved_std.to(torch.float64), recorded_std, rtol=1e-6, atol=1e-8)):
                    raise ValueError("recorded action std differs from checkpoint")
            except Exception as exc:
                raise EvaluationEvidenceError(f"motion action checkpoint std verification failed: {exc}") from exc
    if (telemetry.get("telemetry_status") != "complete"
            or result.get("telemetry_status") != "complete"
            or not MOTION_REQUIRED_SIGNALS.issubset(telemetry.get("required_signals", []))):
        raise EvaluationEvidenceError("incomplete motion telemetry")
    for name in MOTION_REQUIRED_SIGNALS:
        status = telemetry.get("signal_status", {}).get(name, {})
        if (not status.get("complete") or not status.get("required")
                or status.get("sample_count") != len(samples)
                or status.get("expected_sample_count") != len(samples) or status.get("error_count") != 0):
            raise EvaluationEvidenceError(f"incomplete motion signal: {name}")
    names = telemetry.get("joint_names", [])
    bodies = diagnostic.get("body_names", [])
    contacts = diagnostic.get("contact_body_names", [])
    if (not names or len(set(names)) != len(names) or not bodies or
            contacts != ["right_foot_link", "left_foot_link", "right_wheel_link", "left_wheel_link"]):
        raise EvaluationEvidenceError("invalid motion joint/body/contact names")
    widths = {**MOTION_VECTOR_WIDTHS, **{name: len(names) for name in MOTION_JOINT_SIGNALS},
              **{name: len(bodies) * width for name, width in MOTION_BODY_SIGNALS.items()},
              "command": 2 * len(names), "action": len(names), "contact_forces_w": 3 * len(contacts)}
    previous = None
    for i, sample in enumerate(samples):
        if sample.get("step") != i or not MOTION_REQUIRED_SIGNALS.issubset(sample):
            raise EvaluationEvidenceError("missing/out-of-order motion sample")
        stamp = sample.get("sim_time_seconds")
        if type(stamp) not in (int, float) or not math.isclose(stamp, (i + 1) * dt, abs_tol=1e-9):
            raise EvaluationEvidenceError("motion sample time mismatch")
        for name, width in widths.items():
            values = sample.get(name)
            if (not isinstance(values, list) or len(values) != width or
                    any(type(v) not in (float, int) or not math.isfinite(v) for v in values)):
                raise EvaluationEvidenceError(f"invalid motion vector: {name}")
        for name in ("frame_index", "episode_start_frame", "episode_id"):
            if type(sample[name]) is not int or sample[name] < 0:
                raise EvaluationEvidenceError("invalid motion episode/frame index")
        if not sample["episode_start_frame"] <= sample["frame_index"] < count:
            raise EvaluationEvidenceError("motion frame outside episode range")
        if diagnostic["mode"] != "randomized_phase" and sample["episode_start_frame"] != 0:
            raise EvaluationEvidenceError("fixed-start motion episode did not start at zero")
        terms = sample["termination_terms"]
        if (not isinstance(terms, dict) or "motion_finished" not in terms
                or any(type(v) is not bool for v in terms.values())
                or type(sample["done"]) is not bool or type(sample["timeout"]) is not bool
                or sample["done"] != any(terms.values())
                or sample["timeout"] != (terms.get("time_out", False) or terms["motion_finished"])):
            raise EvaluationEvidenceError("inconsistent motion termination signals")
        if terms["motion_finished"] != (sample["frame_index"] == count - 1):
            raise EvaluationEvidenceError("motion end does not match final reference frame")
        if type(sample["reward"]) not in (float, int) or not math.isfinite(sample["reward"]):
            raise EvaluationEvidenceError("nonfinite motion reward")
        if previous is None or previous["done"]:
            if (sample["frame_index"] != sample["episode_start_frame"] or
                    sample["episode_id"] != (0 if previous is None else previous["episode_id"] + 1)):
                raise EvaluationEvidenceError("inconsistent motion episode start")
        elif (sample["frame_index"] != previous["frame_index"] + 1 or
              sample["episode_id"] != previous["episode_id"] or
              sample["episode_start_frame"] != previous["episode_start_frame"]):
            raise EvaluationEvidenceError("motion reference skipped or episode changed without reset")
        previous = sample
    computed = summarize_motion_samples(samples, names, telemetry["joint_effort_limits"])
    for name, value in computed.items():
        actual = result.get("metrics", {}).get(name)
        if type(actual) not in (int, float) or not math.isclose(actual, value, rel_tol=1e-10, abs_tol=1e-12):
            raise EvaluationEvidenceError(f"motion metric differs from telemetry: {name}")
    validate_motion_physics(result, telemetry, scenario)
    validate_motion_ground_contacts(telemetry, scenario)
    validate_landing_pull_telemetry(result, telemetry, scenario)


def validate_motion_ground_contacts(telemetry, scenario):
    """Require a complete normal-force balance with only robot and ground colliders."""
    enabled = scenario["scenario_overrides"].get("evaluation.motion_ground_contacts", False)
    diagnostic = telemetry["motion_diagnostics"].get("ground_contacts")
    samples = telemetry.get("physics_samples", [])
    fields = ("ground_contact_forces_w", "body_net_contact_forces_w",
              "robot_self_contact_forces_w", "ground_contact_body_positions_w")
    if not enabled:
        if diagnostic is not None or any(any(k in s for k in fields) for s in samples):
            raise EvaluationEvidenceError("unbound motion ground contacts")
        return
    if (not isinstance(diagnostic, dict) or diagnostic.get("version") != 1
            or diagnostic.get("body_names") != list(MOTION_GROUND_CONTACT_BODIES)
            or diagnostic.get("sampling_phase") != "after_scene_update_before_reset"
            or diagnostic.get("sensor_type") != "net_minus_robot_self_contacts"
            or diagnostic.get("terrain_type") != "plane"
            or diagnostic.get("contact_positions_available") is not False
            or diagnostic.get("self_filter_prim_paths_expr") != ["/World/envs/env_.*/Robot/.*"]):
        raise EvaluationEvidenceError("invalid motion ground-contact diagnostics")
    ground = diagnostic.get("ground_prim_path")
    robot = diagnostic.get("robot_prim_path")
    colliders = diagnostic.get("scene_collision_prim_paths")
    if (not isinstance(ground, str) or not ground.startswith("/World/")
            or robot != "/World/envs/env_0/Robot" or not samples
            or not isinstance(colliders, list) or not colliders
            or any(not isinstance(v, str) or not any(v.startswith(root + "/") or v == root
                       for root in (ground, robot)) for v in colliders)
            or not any(v.startswith(ground + "/") for v in colliders)):
        raise EvaluationEvidenceError("force balance requires only robot and ground colliders")
    for sample in samples:
        for name in fields:
            values = sample.get(name)
            if (not isinstance(values, list) or len(values) != 12
                    or any(type(v) not in (int, float) or not math.isfinite(v) for v in values)):
                raise EvaluationEvidenceError(f"invalid ground-contact signal: {name}")
        for ground_force, net, self_force in zip(*(sample[name] for name in fields[:3])):
            if not math.isclose(ground_force, net - self_force, rel_tol=1e-6, abs_tol=1e-4):
                raise EvaluationEvidenceError("ground force differs from net minus self contact")
        forces = sample[fields[0]]
        if any(abs(forces[i]) > .05 for i in range(12) if i % 3 != 2) or min(forces[2::3]) < -.05:
            raise EvaluationEvidenceError("residual contact force is inconsistent with a horizontal plane")
        error = sample.get("body_net_sensor_crosscheck_max_abs_error_n")
        if type(error) not in (int, float) or not math.isfinite(error) or not 0 <= error <= .01:
            raise EvaluationEvidenceError("body contact force views disagree")


def validate_landing_pull_telemetry(result, telemetry, scenario):
    from policy_evaluation_telemetry import LandingPullPulse, summarize_landing_pull
    import numpy as np

    config = scenario["scenario_overrides"].get("evaluation.landing_pull")
    if config is None:
        if "landing_pull" in result or "landing_pull" in telemetry:
            raise EvaluationEvidenceError("unbound landing pull telemetry")
        return
    validate_landing_pull_config(config)
    dt = telemetry["motion_diagnostics"]["physics_window"]["physics_dt_seconds"]
    window = scenario["scenario_overrides"]["evaluation.motion_physics_window"]
    if window != [0, telemetry["motion_diagnostics"]["frame_count"] - 1]:
        raise EvaluationEvidenceError("landing pull requires all motion physics substeps")
    diagnostic = telemetry.get("landing_pull", {})
    if diagnostic != result.get("landing_pull") or diagnostic.get("config") != config:
        raise EvaluationEvidenceError("landing pull binding mismatch")
    mass = diagnostic.get("total_mass_kg")
    runtime = telemetry["motion_diagnostics"]["initial_runtime"]
    if type(mass) not in (float, int) or not mass > 0 or not math.isclose(mass, sum(runtime["masses_kg"]), abs_tol=1e-6):
        raise EvaluationEvidenceError("landing pull mass mismatch")
    scheduler = LandingPullPulse(config, dt)
    records = telemetry["physics_samples"]
    heading = np.asarray(diagnostic["forward_w"])
    if heading.shape != (3,) or not np.all(np.isfinite(heading)) or not math.isclose(np.linalg.norm(heading), 1., abs_tol=1e-6) or abs(heading[2]) > 1e-6:
        raise EvaluationEvidenceError("invalid pull forward direction")
    angle = math.radians(config["angle_deg"])
    force = mass * config["delta_v_m_s"] / config["duration_s"] * (heading * math.cos(angle) + np.array([0, 0, math.sin(angle)]))
    widths = {"pull_forward_w": 3, "pull_force_w": 3, "pull_torque_w": 3, "pull_point_w": 3,
              "pull_body_com_w": 3, "root_position_w": 3, "root_linear_velocity_w": 3,
              "root_quaternion_w": 4, "joint_position_target": len(telemetry["joint_names"]),
              "joint_velocity_target": len(telemetry["joint_names"])}
    for r in records:
        for key, width in widths.items():
            a = r.get(key)
            if not isinstance(a, list) or len(a) != width or not np.all(np.isfinite(a)):
                raise EvaluationEvidenceError(f"invalid landing pull signal {key}")
        active = scheduler.active(r["physics_step"], r["episode_id"])
        expected_force = force if active else np.zeros(3)
        if (type(r.get("pull_active")) is not bool or r["pull_active"] != active
                or not np.allclose(r["pull_forward_w"], heading, atol=1e-7, rtol=0)
                or not np.allclose(r["pull_force_w"], expected_force, atol=1e-4, rtol=1e-6)
                or not np.allclose(r["pull_torque_w"], np.cross(np.asarray(r["pull_point_w"]) - r["pull_body_com_w"], expected_force), atol=1e-4, rtol=1e-6)):
            raise EvaluationEvidenceError("landing pull force/torque/schedule mismatch")
        scheduler.observe(r["physics_step"], r["episode_id"], np.asarray(r["contact_forces_w"]).reshape(4, 3)[:, 2])
    if diagnostic.get("summary") != summarize_landing_pull(records, config, dt):
        raise EvaluationEvidenceError("landing pull summary differs from telemetry")


def validate_motion_physics(result, telemetry, scenario):
    """Require every substep of every observed window, including terminal steps."""
    from policy_evaluation_telemetry import (
        MOTION_PHYSICS_VECTOR_WIDTHS, MOTION_PHYSICS_JOINT_SIGNALS, summarize_motion_physics,
    )
    window = scenario["scenario_overrides"].get("evaluation.motion_physics_window")
    diagnostic = telemetry["motion_diagnostics"].get("physics_window")
    if window is None:
        if diagnostic is not None or "physics_samples" in telemetry or "physics_window_metrics" in result:
            raise EvaluationEvidenceError("unbound motion physics telemetry")
        return
    if not isinstance(diagnostic, dict):
        raise EvaluationEvidenceError("missing motion physics diagnostics")
    dt = diagnostic.get("physics_dt_seconds")
    decimation = diagnostic.get("decimation")
    if (diagnostic.get("frame_range_inclusive") != window
            or window[1] >= telemetry["motion_diagnostics"]["frame_count"]
            or type(dt) not in (int, float) or not math.isclose(dt, .005, abs_tol=1e-12)
            or type(decimation) is not int or decimation <= 0
            or not math.isclose(dt * decimation, telemetry["step_dt_seconds"], abs_tol=1e-12)
            or diagnostic.get("sampling_phase") != "after_scene_update_before_reset"
            or diagnostic.get("wheel_body_names") != ["right_wheel_link", "left_wheel_link"]):
        raise EvaluationEvidenceError("motion physics timing/window mismatch")
    control = [s for s in telemetry["samples"] if window[0] <= s["frame_index"] <= window[1]]
    samples = telemetry.get("physics_samples")
    if not isinstance(samples, list) or len(samples) != len(control) * decimation:
        raise EvaluationEvidenceError("missing motion physics samples")
    widths = {**MOTION_PHYSICS_VECTOR_WIDTHS,
              **{k: len(telemetry["joint_names"]) for k in MOTION_PHYSICS_JOINT_SIGNALS}}
    previous = None
    for i, sample in enumerate(samples):
        parent = control[i // decimation]
        substep = i % decimation
        physics_step = parent["step"] * decimation + substep
        expected = {"control_step": parent["step"], "substep": substep, "physics_step": physics_step,
                    **{k: parent[k] for k in ("frame_index", "episode_id", "episode_start_frame")}}
        if any(type(sample.get(k)) is not int or sample[k] != v for k, v in expected.items()):
            raise EvaluationEvidenceError("out-of-order/reset-misaligned motion physics sample")
        stamp = sample.get("sim_time_seconds")
        if type(stamp) not in (int, float) or not math.isclose(stamp, (physics_step + 1) * dt, abs_tol=1e-9):
            raise EvaluationEvidenceError("motion physics timestamp mismatch")
        for name, width in widths.items():
            values = sample.get(name)
            if (not isinstance(values, list) or len(values) != width
                    or any(type(v) not in (int, float) or not math.isfinite(v) for v in values)):
                raise EvaluationEvidenceError(f"invalid motion physics signal: {name}")
        if previous is not None and previous["episode_id"] == sample["episode_id"] and previous["physics_step"] + 1 == physics_step:
            if sample["wheel_center_velocity_before_w"] != previous["wheel_center_velocity_w"]:
                raise EvaluationEvidenceError("motion physics before/after velocity discontinuity")
        if substep == decimation - 1:
            for name in ("contact_forces_w", "applied_torque", "computed_torque", "joint_velocity"):
                if sample[name] != parent[name]:
                    raise EvaluationEvidenceError(f"physics/control endpoint mismatch: {name}")
        previous = sample
    expected_metrics = summarize_motion_physics(samples, telemetry["joint_effort_limits"], dt)
    if result.get("physics_window_metrics") != expected_metrics:
        raise EvaluationEvidenceError("motion physics metrics differ from telemetry")

from __future__ import annotations

import math
import numpy as np
import os
import torch
from collections.abc import Sequence
from dataclasses import MISSING
